import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed } from './src/workspace.js';

const feed = createProgressFeed({ initialPacket: { percent: 5 } });
const queue = [];
const history = [];
const panel = [];
const notices = [];
const workspace = createTransferWorkspace({
  transport() {},
  onCancel() {},
  record: value => queue.push(value),
  showQueued: value => notices.push(value),
  recordProgress: value => history.push(value),
  showProgress: value => panel.push(value),
});
const file = { id: 'file-a', progressFeed: feed, size: 99 };
workspace.select(file);
assert.deepEqual(queue, [{ fileId: 'file-a', attemptId: 1, visitId: 1, kind: 'select' }]);
assert.deepEqual(panel, [{ fileId: 'file-a', attemptId: 1, frame: { percent: 5 } }]);
workspace.retry();
assert.deepEqual(queue, [
  { fileId: 'file-a', attemptId: 1, visitId: 1, kind: 'select' },
  { fileId: 'file-a', attemptId: 2, visitId: 1, kind: 'retry' },
]);
assert.equal(history.length, 2);
assert.equal(notices.length, 2);
console.log('workspace integration checks passed');
